def containsCycle(grid):
    def dfs(x, y, prev_x, prev_y, char):
        if (x, y) in visited:
            return True
        visited.add((x, y))
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == char and (nx != prev_x or ny != prev_y):
                if dfs(nx, ny, x, y, char):
                    return True
        return False

    m, n = len(grid), len(grid[0])
    visited = set()
    for i in range(m):
        for j in range(n):
            if (i, j) not in visited:
                if dfs(i, j, -1, -1, grid[i][j]):
                    return True
    return False
